package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Product struct {
	ID          int     `json:"id"`
	Name        string  `json:"name"`
	Category    string  `json:"category"`
	Price       float64 `json:"price"`
	SupplierRef string  `json:"supplier_ref"`
}

func init() {
	var err error
	dsn := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", dsn)
	if err != nil {
		log.Fatal(err)
	}
	db.SetMaxOpenConns(25)
	db.SetMaxIdleConns(5)
}

// getProduct uses parameterized query - safe
func getProduct(w http.ResponseWriter, r *http.Request) {
	id := r.URL.Query().Get("id")
	row := db.QueryRow("SELECT id, name, category, price, supplier_ref FROM products WHERE id = $1", id)
	var p Product
	if err := row.Scan(&p.ID, &p.Name, &p.Category, &p.Price, &p.SupplierRef); err != nil {
		http.Error(w, "not found", 404)
		return
	}
	json.NewEncoder(w).Encode(p)
}

// filterProducts builds dynamic filter - VULNERABLE
func filterProducts(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	minPrice := r.URL.Query().Get("min_price")
	sortCol := r.URL.Query().Get("sort")

	// Validate sort column
	allowedSorts := map[string]bool{"name": true, "price": true, "category": true}
	if sortCol == "" || !allowedSorts[sortCol] {
		sortCol = "name"
	}

	// Validate min_price is numeric-ish (weak check)
	if minPrice == "" {
		minPrice = "0"
	}

	// Build query - category is NOT parameterized
	var query string
	if category != "" {
		// Developer thought single quotes in category would be caught by frontend
		query = fmt.Sprintf(
			"SELECT id, name, category, price, supplier_ref FROM products WHERE category = '%s' AND price >= %s ORDER BY %s LIMIT 50",
			category, minPrice, sortCol,
		)
	} else {
		query = fmt.Sprintf(
			"SELECT id, name, category, price, supplier_ref FROM products WHERE price >= %s ORDER BY %s LIMIT 50",
			minPrice, sortCol,
		)
	}

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("query error: %v", err)
		http.Error(w, "internal error", 500)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		rows.Scan(&p.ID, &p.Name, &p.Category, &p.Price, &p.SupplierRef)
		products = append(products, p)
	}
	json.NewEncoder(w).Encode(products)
}

// healthCheck endpoint for LB
func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

// adminResetCache - requires X-Admin-Token header
func adminResetCache(w http.ResponseWriter, r *http.Request) {
	token := r.Header.Get("X-Admin-Token")
	expected := os.Getenv("ADMIN_TOKEN")
	if token == "" || !strings.EqualFold(token, expected) {
		http.Error(w, "forbidden", 403)
		return
	}
	// Reset prepared statement cache
	db.SetMaxIdleConns(0)
	db.SetMaxIdleConns(5)
	w.Write([]byte("cache reset"))
}

func main() {
	http.HandleFunc("/api/product", getProduct)
	http.HandleFunc("/api/products/filter", filterProducts)
	http.HandleFunc("/health", healthCheck)
	http.HandleFunc("/admin/reset-cache", adminResetCache)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("listening on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
